-- iPhone intake choices: keep existing option IDs, stock and production history.
begin;
do $$begin if public.get_stock_batch_links_version()is distinct from '20261027-stock-batches-1'then raise exception 'Verified Stock Batch Links are required.';end if;if to_regprocedure('public.get_iphone_entry_options_version()')is not null then if public.get_iphone_entry_options_version()is distinct from '20261027-iphone-entry-options-1'then raise exception 'Existing iPhone entry options need review.';end if;end if;end;$$;
create table if not exists greenloop_private.iphone_entry_seed(option_group text not null,option_value text not null,option_id uuid not null,primary key(option_group,option_value));
alter table greenloop_private.iphone_entry_seed enable row level security;revoke all on greenloop_private.iphone_entry_seed from public,anon,authenticated;
create or replace function greenloop_private.ic_storage(p_value text)returns integer language plpgsql immutable set search_path=pg_catalog as $$declare v text:=upper(regexp_replace(btrim(p_value),'[[:space:]]+','','g'));n numeric;begin
 if v is null or v!~'^[0-9]+(GB|TB)?$'or length(v)>15 then return null;end if;n:=regexp_replace(v,'(GB|TB)$','')::numeric;if v like '%TB'then n:=n*1024;end if;if n<1 or n>2147483647 then return null;end if;return n::integer;
end;$$;
do $seed$declare r record;chosen uuid;begin perform pg_advisory_xact_lock(20720261027);
 for r in select 'model'::text kind,name value from greenloop_private.closing_stock_options where kind='model'and active
 union all select 'storage_gb',unnest(array['64','128','256','512','1024','2048'])
 union all select 'color',unnest(array['Alpine Green','Black','Black & Slate','Black Titanium','Blue','Blue Titanium','Burgundy','Cloud White','Coral','Cosmic Orange','Deep Blue','Deep Purple','Desert Titanium','Glacier','Gold','Graphite','Green','Jet Black','Lavender','Light Gold','Midnight','Midnight Green','Mist Blue','Natural Titanium','Night Sky','Pacific Blue','Pink','(PRODUCT)RED','Purple','Rose Gold','Sage','Sierra Blue','Silver','Sky Blue','Soft Pink','Space Black','Space Gray','Star White','Starlight','Teal','Ultramarine','White','White & Silver','White Titanium','Yellow'])loop
 if exists(select 1 from greenloop_private.iphone_entry_seed where option_group=r.kind and option_value=r.value)then continue;end if;
 select id into chosen from public.entry_options where option_group=r.kind and lower(regexp_replace(btrim(option_value),'[[:space:]]+',' ','g'))=lower(r.value)order by is_active desc,created_at,id limit 1;
 if chosen is null then insert into public.entry_options(option_group,option_value,is_active,created_by)values(r.kind,r.value,true,auth.uid())returning id into chosen;else update public.entry_options set is_active=true where id=chosen;end if;
 insert into greenloop_private.iphone_entry_seed values(r.kind,r.value,chosen);
 end loop;end;$seed$;
create or replace function public.get_imei_entry_choices_v1(p_option_group text)returns table(id uuid,option_value text)language plpgsql stable security definer set search_path=pg_catalog,public as $$begin
 perform greenloop_private.pf_cap('imei_entry','view');if p_option_group is null or p_option_group not in ('model','storage_gb','color')then raise exception 'Choose a valid IMEI entry list.'using errcode='22023';end if;
 if p_option_group='storage_gb'then return query select q.id,q.gb::text from(select distinct on(greenloop_private.ic_storage(o.option_value))o.id,greenloop_private.ic_storage(o.option_value)gb from public.entry_options o where o.option_group=p_option_group and o.is_active and greenloop_private.ic_storage(o.option_value)is not null order by greenloop_private.ic_storage(o.option_value),(o.option_value=greenloop_private.ic_storage(o.option_value)::text)desc,o.created_at,o.id)q order by q.gb;
 else return query select o.id,o.option_value from public.entry_options o where o.option_group=p_option_group and o.is_active order by lower(o.option_value),o.id;end if;
end;$$;
insert into greenloop_private.capability_rpc_rules values('get_imei_entry_choices_v1','{"page":"imei_entry","capability":"view","read":true}'::jsonb)on conflict(rpc_name)do update set rule=excluded.rule;
update greenloop_private.page_capability_installation set hash=(select md5(jsonb_agg(to_jsonb(r)order by rpc_name)::text)from greenloop_private.capability_rpc_rules r)where identity='rules';
do $wrap$declare f record;impl text;impl_identity text;args text;body text;begin
 for f in select p.*,pg_get_functiondef(p.oid)ddl,p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='public'::regnamespace and p.proname in ('get_imei_entry_choices_v1')loop
 impl:='office_impl_'||f.oid;execute regexp_replace(f.ddl,'FUNCTION public\.'||f.proname||'\(','FUNCTION greenloop_private.'||impl||'(');impl_identity:='greenloop_private.'||impl||'('||oidvectortypes(f.proargtypes)||')';execute format('revoke all on function %s from public,anon,authenticated',impl_identity);select coalesce(string_agg('$'||i,','order by i),'')into args from generate_series(1,f.pronargs)i;
 body:=E'begin\n -- greenloop-office-wrapper-196\n perform greenloop_private.require_office_network();\n return query select *from greenloop_private.'||impl||'('||args||E');\nend;';execute format('create or replace function public.%I(%s)returns %s language plpgsql %s security definer set search_path=pg_catalog,public as %L',f.proname,pg_get_function_arguments(f.oid),pg_get_function_result(f.oid),case f.provolatile when 's'then 'stable'else 'volatile'end,body);execute format('revoke all on function %s from public,anon,authenticated',f.signature);execute format('grant execute on function %s to authenticated',f.signature);insert into greenloop_private.office_routines values(f.signature,impl_identity,md5(pg_get_functiondef(impl_identity::regprocedure)),md5(pg_get_functiondef(f.oid)))on conflict(identity)do update set implementation=excluded.implementation,original_hash=excluded.original_hash,wrapped_hash=excluded.wrapped_hash;
 end loop;for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='greenloop_private'::regnamespace and p.proname='ic_storage'loop execute format('revoke all on function %s from public,anon,authenticated',f.signature);end loop;
end;$wrap$;
create table if not exists greenloop_private.iphone_entry_installation(identity text primary key,hash text not null);alter table greenloop_private.iphone_entry_installation enable row level security;revoke all on greenloop_private.iphone_entry_installation from public,anon,authenticated;
insert into greenloop_private.iphone_entry_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where(p.pronamespace='public'::regnamespace and p.proname='get_imei_entry_choices_v1')or(p.pronamespace='greenloop_private'::regnamespace and p.proname='ic_storage')on conflict(identity)do update set hash=excluded.hash;
create or replace function public.get_iphone_entry_options_version()returns text language sql stable security definer set search_path=pg_catalog,public as $$select case when public.get_stock_batch_links_version()='20261027-stock-batches-1'
 and(select count(*)=2 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.iphone_entry_installation)
 and not exists(select 1 from unnest(array['iphone_entry_seed','iphone_entry_installation'])t where has_table_privilege('authenticated','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('anon','greenloop_private.'||t,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'))
 and not has_function_privilege('authenticated','greenloop_private.ic_storage(text)','EXECUTE')and not has_function_privilege('anon','greenloop_private.ic_storage(text)','EXECUTE')then '20261027-iphone-entry-options-1'end;$$;
revoke all on function public.get_iphone_entry_options_version()from public;grant execute on function public.get_iphone_entry_options_version()to anon,authenticated;
do $$begin if public.get_iphone_entry_options_version()is distinct from '20261027-iphone-entry-options-1'then raise exception 'iPhone entry options verification failed.';end if;end;$$;
notify pgrst,'reload schema';commit;
select public.get_iphone_entry_options_version()as installed_iphone_entry_options_version;
